{"content": """"Relay local: entrega bytes (JSON/base64) à pagina do WhatsApp Web via window.name.

CSP do web.whatsapp.com bloqueia fetch para localhost, mas navegacao de topo
nao e bloqueada. Esta pagina roda em 127.0.0.1, grava o payload em window.name
e redireciona para o app, que entao le window.name.
"""
import base64, json, sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs, unquote

TARGET = "https://web.whatsapp.com/"

PAGE = """<!doctype html><meta charset="utf-8"><title>relay</title>
<body style="font:14px system-ui;background:#111;color:#eee">
<p id="s">gravando window.name...</p>
<script>
const payload = %s;
try {
  window.name = payload;
  document.getElementById('s').textContent = 'window.name=' + payload.length + ' bytes, indo para o app...';
  setTimeout(() => location.replace(%s), 150);
} catch (e) {
  document.getElementById('s').textContent = 'ERRO: ' + e.message;
}
</script></body>"""


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def do_GET(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path == "/relay" and "d" in q:
            raw = base64.urlsafe_b64decode(q["d"][0] + "==")
            body = (PAGE % (json.dumps(raw.decode("utf-8")), json.dumps(TARGET))).encode("utf-8")
        elif u.path == "/ping":
            body = b"pong"
        else:
            self.send_response(404); self.end_headers(); return
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8766
    ThreadingHTTPServer(("127.0.0.1", port), H).serve_forever()
