CSP do web.whatsapp.com bloqueia fetch/script para localhost; navegacao de topo
nao e bloqueada. Esta pagina roda em 127.0.0.1, grava o payload em window.name
e redireciona para o app, que entao le window.name.

GET /relay?f=<arquivo>   -> embute o conteudo do arquivo (JSON ou base64 de imagem)
GET /relay?f=...&t=<url> -> alvo de redirecionamento customizado
GET /ping
"""
import json, os, sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

HERE = os.path.dirname(os.path.abspath(__file__))
DEFAULT_TARGET = "https://web.whatsapp.com/"

PAGE = """<!doctype html><meta charset="utf-8"><title>relay</title>
<body style="font:14px system-ui;background:#111;color:#eee">
<p id="s">gravando window.name...</p>
<script>
const payload = %(payload)s;
try {
  window.name = payload;
  document.getElementById('s').textContent = 'window.name OK: ' + payload.length + ' bytes -> ' + %(target_txt)s;
  setTimeout(() => location.replace(%(target)s), 200);
} catch (e) {
  document.getElementById('s').textContent = 'ERRO: ' + e.message;
}
</script></body>"""


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, body, code=200):
        self.send_response(code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path == "/ping":
            return self._send(b"pong")
        if u.path != "/relay" or "f" not in q:
            return self._send(b"use /relay?f=<file>", 404)

        name = os.path.basename(q["f"][0])
        path = os.path.join(HERE, name)
        if not os.path.isfile(path):
            return self._send(f"arquivo ausente: {name}".encode(), 404)

        with open(path, "r", encoding="utf-8") as fh:
            content = fh.read()
        target = q.get("t", [DEFAULT_TARGET])[0]
        body = (PAGE % {
            "payload": json.dumps(content),
            "target": json.dumps(target),
            "target_txt": json.dumps(target),
        }).encode("utf-8")
        self._send(body)


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8766
    ThreadingHTTPServer(("127.0.0.1", port), H).serve_forever()
